import { useState, useEffect } from 'react';
import axios from 'axios';

const Category = () => {
  const [categories, setCategories] = useState([]);
  const [name, setName] = useState('');
  const [image, setImage] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/users/allcategories');
      setCategories(response.data);
    } catch (error) {
      console.error("Error fetching categories:", error);
    }
  };

  const handleAddCategory = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("name", name);
    formData.append("image", image);

    try {
      const response = await axios.post('http://localhost:5000/api/users/addcategory', formData, {
        headers: {
          "Content-Type": "multipart/form-data"
        }
      });
      console.log("Category added:", response.data);
      setName('');
      setImage(null);
      fetchCategories();
    } catch (error) {
      console.error("Error adding category:", error);
    }
  };

  return (
    <div style={styles.wrapper}>
      {/* Left: Category Cards */}
      <div style={styles.left}>
        <h2 style={styles.title}>📁 Categories</h2>
        <div style={styles.grid}>
          {categories
            .filter((cat) => cat.name.toLowerCase().includes(searchTerm.toLowerCase()))
            .map((cat) => (
              <div
                key={cat._id}
                style={styles.card}
                onMouseOver={(e) => e.currentTarget.style.transform = "translateY(-6px)"}
                onMouseOut={(e) => e.currentTarget.style.transform = "translateY(0px)"}
              >
                <img
                  src={`http://localhost:5000/uploads/${cat.image}`}
                  alt={cat.name}
                  style={styles.image}
                />
                <div style={styles.cardFooter}>
                  <h4 style={styles.cardTitle}>{cat.name}</h4>
                </div>
              </div>
            ))}
        </div>
      </div>

      {/* Right: Add Category */}
      <div style={styles.right}>
        <h2 style={styles.rightHeading}>🔍 Search Categories</h2>
        <input
          type="text"
          placeholder="Search..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={styles.searchInput}
        />

        <h2 style={styles.rightHeading}>➕ Add New Category</h2>
        <form
          onSubmit={handleAddCategory}
          encType="multipart/form-data"
          style={styles.form}
        >
          <input
            type="text"
            placeholder="Category Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            style={styles.input}
          />
          <input
            type="file"
            accept="image/*"
            onChange={(e) => setImage(e.target.files[0])}
            required
            style={styles.input}
          />
          <button type="submit" style={styles.button}>
            Add Category
          </button>
        </form>
      </div>
    </div>
  );
};

const styles = {
  wrapper: {
    display: "flex",
    padding: "50px",
    fontFamily: "Segoe UI, sans-serif",
    gap: "40px",
    alignItems: "flex-start",
    backgroundColor: "#f2f6fc",
    minHeight: "100vh",
  },
  left: {
    flex: 1,
  },
  title: {
    fontSize: "34px",
    color: "#1e1e1e",
    marginBottom: "30px",
  },
  grid: {
    display: "flex",
    flexWrap: "wrap",
    gap: "24px",
  },
  card: {
    width: "230px",
    borderRadius: "12px",
    overflow: "hidden",
    backgroundColor: "#fff",
    boxShadow: "0 8px 20px rgba(0,0,0,0.1)",
    transition: "transform 0.3s ease",
    cursor: "pointer",
  },
  image: {
    width: "100%",
    height: "200px",
    objectFit: "cover",
  },
  cardFooter: {
    padding: "14px",
    textAlign: "center",
  },
  cardTitle: {
    margin: 0,
    fontSize: "18px",
    color: "#333",
  },
  right: {
    width: "340px",
    backgroundColor: "#ffffff",
    border: "1px solid #ddd",
    borderRadius: "12px",
    boxShadow: "0 6px 20px rgba(0,0,0,0.08)",
    padding: "25px",
    position: "sticky",
    top: "100px",
  },
  rightHeading: {
    fontSize: "20px",
    marginBottom: "10px",
    color: "#222",
  },
  searchInput: {
    width: "100%",
    padding: "10px",
    fontSize: "15px",
    borderRadius: "8px",
    border: "1px solid #ccc",
    marginBottom: "30px",
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "16px",
  },
  input: {
    padding: "10px",
    fontSize: "15px",
    borderRadius: "8px",
    border: "1px solid #ccc",
  },
  button: {
    padding: "12px",
    fontSize: "16px",
    backgroundColor: "#1f2937",
    color: "#fff",
    borderRadius: "8px",
    border: "none",
    cursor: "pointer",
    transition: "background 0.3s ease",
  },
};

export default Category;
